use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_lowercase_char(c: char) -> bool {
    'a' <= c && c <= 'z'
}

spec fn all_lowercase_spec(v: &Vec<char>) -> bool {
    forall|i: int| 0 <= i && i < v.len() ==> is_lowercase_char(v[i])
}

spec fn solve_spec(v: Vec<char>) -> Vec<char> {
    if v.len() > 0 && all_lowercase_spec(&v) {
        vec!['a']
    } else {
        vec!['A']
    }
}

fn check_all_lowercase(v: &Vec<char>) -> (result: bool)
    ensures
        result == (v.len() > 0 && all_lowercase_spec(v))
{
    if v.len() == 0 {
        return false;
    }
    
    let mut i: usize = 0;
    while i < v.len()
        invariant
            0 <= i <= v.len(),
            forall|j: int| 0 <= j < i ==> is_lowercase_char(v[j]),
        decreases v.len() - i,
    {
        let c = v[i];
        if !('a' <= c && c <= 'z') {
            return false;
        }
        i = i + 1;
    }
    
    true
}

fn solve(input: Vec<char>) -> (output: Vec<char>)
    ensures
        output == solve_spec(input),
        output.len() == 1,
        output[0] == 'a' || output[0] == 'A'
{
    let all_lower = check_all_lowercase(&input);
    
    if input.len() > 0 && all_lower {
        vec!['a']
    } else {
        vec!['A']
    }
}

}
